import { useEffect, useState, useRef, useCallback } from "react";
import {
  Button,
  Grid,
  IconButton,
  MenuItem,
  Select,
  Typography,
} from "@mui/material";
import Card from "@mui/material/Card";
import Box from "@mui/material/Box";
import TextField from "@mui/material/TextField";
import PageHeader from "src/@core/components/page-header";
import Translations from "src/layouts/components/Translations";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import { DefaultPaginationSettings } from "src/constants/general.const";
import { toastError, toastSuccess } from "src/utils/utils";
import DialogConfirmation from "src/views/dialog/DialogConfirmation";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import DialogAdditionalFeatures from "src/views/dialog/IT-Solution-Features/DialogAdditionalFeatures";
import TableAdditionalFeaturesList from "src/views/tables/IT-Solution-Features/TableAdditionalFeaturesList";
import DialogAdditionalFeaturesList from "src/views/dialog/IT-Solution-Features/DialogAdditionalFeaturesList";
import DialogDeleteAddFeaturesList from "src/views/dialog/IT-Solution-Features/DialogDeleteAddFeaturesList";
import DialogEditAdditionalFeaturesList from "src/views/dialog/IT-Solution-Features/DialogEditAdditionalFeaturesList";

const ITSolutionAdditionalFeaturesList = () => {
  const navigate = useNavigate();
  const searchTimeoutRef = useRef();
  const [loading, setLoading] = useState(false);
  const [additionalFeatureList, setAdditionalFeatureList] = useState([]);
  const [search, setSearch] = useState("");
  const [totalCount, setTotalCount] = useState(0);
  const [currentPage, setCurrentPage] = useState(1);
  const [pageSize, setPageSize] = useState(
    DefaultPaginationSettings.ROWS_PER_PAGE
  );
  const [status, setStatus] = useState("");
  const { id } = useParams();
  const location = useLocation();
  // Testimonials
  const [listFormDialogOpen, setListFormDialogOpen] = useState(false);
  const [listFormDialogMode, setListFormDialogMode] = useState("add");
  const [additionalFeatureDetailToEdit, setAdditionalFeatureDetailToEdit] =
    useState(null);
  // Confirmation
  const [confirmationDialogLoading, setConfirmationDialogLoading] =
    useState(false);
  const [confirmationDialogOpen, setConfirmationDialogOpen] = useState(false);

  //for selecting the point to delete
  const [additionalFeatureDetailToDelete, setAdditionalFeatureDetailToDelete] =
    useState(null);
  const [deleteFeaturesListOpen, setDeleteFeaturesListOpen] = useState(false);
  //for editing points
  const [editPointDialogOpen, setEditPointDialogOpen] = useState(false);

  //  opening dialog for adding points
  const toggleAdditionalFeaturesFormDialog = (
    e,
    mode = "add",
    dataToEdit = null
  ) => {
    setListFormDialogOpen((prev) => !prev);
    // setListFormDialogMode(mode);
    // setAdditionalFeatureDetailToEdit(additionalFeatureDetailToEdit);
  };

  //  opening dialog for editing points
  const toggleEditPointDialog = (e, dataToEdit = null) => {
    setEditPointDialogOpen((prev) => !prev);
    setAdditionalFeatureDetailToEdit(dataToEdit);
  };

  // opening dialog for selecting the point to delete
  const toggleDeleteFeatureListDialog = (e, dataToDelete = null) => {
    setAdditionalFeatureDetailToDelete(dataToDelete);
    setDeleteFeaturesListOpen((prev) => !prev);
  };
  // opening dialog for delete confirmation dialog
  const toggleConfirmationDialog = (e, dataToDelete = null) => {
    setConfirmationDialogOpen((prev) => !prev);
    if (dataToDelete) {
      setAdditionalFeatureDetailToDelete(dataToDelete);
    }
  };

  const fetchData = ({
    currentPage,
    pageSize = DefaultPaginationSettings.ROWS_PER_PAGE,
    search,
    status,
  }) => {
    setLoading(true);
    let params = {
      page: currentPage,
      limit: pageSize,
      search: search,
      status: status,
    };

    axiosInstance
      .get(ApiEndPoints.ITSolutionAdditionalFeaturesList.list(id), { params })
      .then((response) => {
        const responseData = response.data.data;
        console.log(responseData);
        setAdditionalFeatureList(responseData);
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };

  useEffect(() => {
    fetchData({
      currentPage: currentPage,
      pageSize: pageSize,
      search: search,
      status: status,
    });
  }, [currentPage, pageSize, search, status]);

  const handleSearchChange = (e) => {
    if (searchTimeoutRef.current) {
      clearTimeout(searchTimeoutRef.current);
    }

    searchTimeoutRef.current = setTimeout(() => {
      setSearch(e.target.value);
    }, 500);
  };

  const onConfirmDelete = useCallback(
    (e) => {
      e?.preventDefault();
      setConfirmationDialogLoading(true);
      console.log("ID", additionalFeatureDetailToDelete);
      axiosInstance
        .delete(
          ApiEndPoints.ITSolutionAdditionalFeaturesList.delete(
            additionalFeatureDetailToDelete
          )
        )
        .then((response) => response.data)
        .then((response) => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
            search: search,
          });
          toastSuccess(response.message);
          toggleConfirmationDialog();
          toggleDeleteFeatureListDialog();
        })
        .catch((error) => {
          toastError(error);
        })
        .finally(() => {
          setConfirmationDialogLoading(false);
          setDeleteFeaturesListOpen(false);
        });
    },
    [currentPage, additionalFeatureDetailToDelete, pageSize, search]
  );

  const handleIconClick = () => {
    navigate(-1);
  };
  return (
    <>
      <Grid container spacing={4} className="match-height">
        <PageHeader
          title={
            <Typography variant="h5">
              <Translations text={location.state?.title} />
            </Typography>
          }
          action={
            <Button
              variant="contained"
              onClick={toggleAdditionalFeaturesFormDialog}
            >
              Add Additional Features Description
            </Button>
          }
          backNavigation={
            <IconButton
              sx={{
                height: "30px",
                width: "30px",
                borderRadius: "50px",
                border: "2px solid #602de1c2",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
              }}
              onClick={handleIconClick}
            >
              <ArrowBackIcon sx={{ color: "#602de1c2", fontSize: "18px" }} />
            </IconButton>
          }
        />
        <Grid item xs={12}>
          <Card>
            {/* <Box
              sx={{
                p: 5,
                pb: 0,
                display: "flex",
                flexWrap: "wrap",
                alignItems: "center",
                justifyContent: "end",
              }}
            >
              <Box
                sx={{
                  display: "flex",
                  flexWrap: "wrap",
                  alignItems: "center",
                  gap: 5,
                }}
              >
                <Select
                  size="small"
                  defaultValue={" "}
                  sx={{ bgcolor: "#F7FBFF" }}
                  onChange={(e) => {
                    const selectedValue = e.target.value;
                    setStatus(selectedValue === "All" ? "" : selectedValue);
                  }}
                >
                  <MenuItem disabled value={" "}>
                    <em>Status</em>
                  </MenuItem>
                  <MenuItem value={"All"}>All</MenuItem>
                  <MenuItem value={"active"}>Active</MenuItem>
                  <MenuItem value={"inactive"}>Inactive</MenuItem>
                </Select>
                <TextField
                  type="search"
                  size="small"
                  placeholder="Search"
                  onChange={handleSearchChange}
                />
              </Box>
            </Box> */}
            <Box sx={{ p: 5 }}>
              <TableAdditionalFeaturesList
                search={search}
                loading={loading}
                rows={additionalFeatureList}
                totalCount={totalCount}
                setCurrentPage={setCurrentPage}
                currentPage={currentPage}
                setPageSize={setPageSize}
                pageSize={pageSize}
                // toggleDelete={toggleConfirmationDialog}
                toggleDelete={toggleDeleteFeatureListDialog}
                // toggleEdit={toggleAdditionalFeaturesFormDialog}
                toggleEdit={toggleEditPointDialog}
              />
            </Box>
          </Card>
        </Grid>
      </Grid>
      <DialogAdditionalFeaturesList
        mode={listFormDialogMode}
        open={listFormDialogOpen}
        toggle={toggleAdditionalFeaturesFormDialog}
        dataToEdit={additionalFeatureDetailToEdit}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogEditAdditionalFeaturesList
        open={editPointDialogOpen}
        dataToEdit={additionalFeatureDetailToEdit}
        toggle={toggleEditPointDialog}
        onSuccess={() => {
          fetchData({
            currentPage: currentPage,
            pageSize: pageSize,
          });
        }}
      />
      <DialogConfirmation
        loading={confirmationDialogLoading}
        title="Delete"
        subtitle="Are you sure you want to delete this?"
        open={confirmationDialogOpen}
        toggle={toggleConfirmationDialog}
        onConfirm={onConfirmDelete}
      />

      <DialogDeleteAddFeaturesList
        open={deleteFeaturesListOpen}
        toggle={toggleDeleteFeatureListDialog}
        itemDataToDelete={additionalFeatureDetailToDelete}
        toggleDelete={toggleConfirmationDialog}
      />
    </>
  );
};

export default ITSolutionAdditionalFeaturesList;
