import React, { useEffect, useState } from "react";
import {
  Box,
  Button,
  Card,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  FormControlLabel,
  Radio,
  TextField,
  FormControl,
  FormHelperText,
} from "@mui/material";
import { Controller, useForm } from "react-hook-form";
import { axiosInstance } from "src/network/adapter";
import { ApiEndPoints } from "src/network/endpoints";
import * as yup from "yup";
import { toastError, toastSuccess } from "src/utils/utils";
import { LoadingButton } from "@mui/lab";
import { yupResolver } from "@hookform/resolvers/yup";

const validationSchema = yup.object().shape({
  point: yup.string().trim().required("Please enter Text to edit."),
});

const DialogEditAdditionalFeaturesList = (props) => {
  const { open, toggle, dataToEdit, onSuccess } = props;
  const [pointToEdit, setPointToEdit] = useState([]);
  const [selectedPointToEdit, setSelectedPointToEdit] = useState("");
  const [textFieldValue, setTextFieldValue] = useState("");
  const [loading, setLoading] = useState(false);

  const {
    control,
    handleSubmit,
    reset,
    setValue,
    formState: { errors },
  } = useForm({
    defaultValues: {
      point: "",
    },
    resolver: yupResolver(validationSchema),
    mode: "onChange",
  });

  useEffect(() => {
    setPointToEdit(dataToEdit?.descriptions);
  }, [dataToEdit]);

  const handleRadioChange = (event, point) => {
    setSelectedPointToEdit(point.id);
    setTextFieldValue(point.text);
    console.log(point.text);
  };
  useEffect(() => {
    console.log("selectedPointToEdit", selectedPointToEdit);
  }, [selectedPointToEdit]);

  const onSubmit = () => {
    let payload = {
      newText: textFieldValue,
    };

    setLoading(true);
    let apiInstance = null;
    apiInstance = axiosInstance.patch(
      ApiEndPoints.ITSolutionAdditionalFeaturesList.edit(selectedPointToEdit),
      payload
    );
    apiInstance
      .then((response) => response.data)
      .then((response) => {
        onSuccess();
        toastSuccess(response.message);
        toggle();
        setTextFieldValue("");
        setSelectedPointToEdit("");
      })
      .catch((error) => {
        toastError(error);
      })
      .finally(() => {
        setLoading(false);
      });
  };
  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        PaperProps={{ sx: { borderRadius: "30px" } }}
      >
        <Card
          sx={{
            display: "flex",
            alignItems: "center",
            flexDirection: "column",
            py: "20px",
            px: "15px",
            textAlign: "center",
            borderRadius: "42px",
          }}
        >
          <DialogTitle>Select Point to Edit</DialogTitle>
          <DialogContent>
            <form
              id="additional-features-form"
              onSubmit={handleSubmit(onSubmit)}
            >
              <Box sx={{ display: "flex", flexDirection: "column" }}>
                {pointToEdit?.map((item, index) => (
                  <FormControlLabel
                    key={index}
                    control={
                      <Radio
                        checked={selectedPointToEdit === item.id}
                        onChange={(e) => handleRadioChange(e, item)}
                      />
                    }
                    label={item.text}
                  />
                ))}

                <FormControl fullWidth sx={{ mb: 4 }}>
                  <Controller
                    name="point"
                    control={control}
                    render={({ field }) => (
                      <TextField
                        {...field}
                        placeholder="Edit Point"
                        variant="outlined"
                        fullWidth
                        margin="normal"
                        error={Boolean(errors.point)}
                        onChange={(e) => {
                          const value = e.target.value;
                          setTextFieldValue(value); // Update local state
                          field.onChange(value); // Update react-hook-form state
                        }}
                        value={textFieldValue}
                      />
                    )}
                  />

                  {errors.point && (
                    <FormHelperText sx={{ color: "error.main" }}>
                      {errors.point.message}
                    </FormHelperText>
                  )}
                </FormControl>
              </Box>
            </form>
          </DialogContent>
          <DialogActions>
            <Button onClick={toggle} variant="outlined">
              Cancel
            </Button>
            <LoadingButton
              size="large"
              type="submit"
              form="additional-features-form"
              variant="contained"
              loading={loading}
            >
              Submit
            </LoadingButton>
          </DialogActions>
        </Card>
      </Dialog>
    </>
  );
};

export default DialogEditAdditionalFeaturesList;
