import React, { useEffect, useState } from "react";
import {
  Box,
  Button,
  Card,
  Checkbox,
  Dialog,
  DialogActions,
  DialogContent,
  DialogContentText,
  DialogTitle,
  FormControlLabel,
  Radio,
} from "@mui/material";

const DialogDeleteAddFeaturesList = (props) => {
  const { open, toggle, itemDataToDelete, toggleDelete } = props;
  const [dataToDelete, setDataToDelete] = useState([]);
  const [selectedPointToDelete, setSelectedPointToDelete] = useState("");

  useEffect(() => {
    setDataToDelete(itemDataToDelete?.descriptions);
  }, [itemDataToDelete]);

  const handleRadioChange = (event, point) => {
    setSelectedPointToDelete(point.id);
  };

  const handleDeleteClick = (e) => {
    e.stopPropagation();
    toggleDelete(e, selectedPointToDelete);
  };
  return (
    <>
      <Dialog
        open={open}
        onClose={toggle}
        PaperProps={{ sx: { borderRadius: "25px" } }}
      >
        <Card
          sx={{
            display: "flex",
            alignItems: "center",
            flexDirection: "column",
            py: "20px",
            px: "15px",
            textAlign: "center",
            borderRadius: "42px",
          }}
        >
          <DialogTitle>Select Point to Delete</DialogTitle>
          <DialogContent>
            <Box sx={{ display: "flex", flexDirection: "column" }}>
              {dataToDelete?.map((item, index) => (
                <FormControlLabel
                  key={index}
                  control={
                    <Radio
                      checked={selectedPointToDelete === item.id}
                      onChange={(e) => handleRadioChange(e, item)}
                    />
                  }
                  label={item.text}
                />
              ))}
            </Box>
          </DialogContent>
          <DialogActions>
            <Button onClick={toggle} variant="outlined">
              Cancel
            </Button>
            <Button onClick={handleDeleteClick} variant="contained">
              Delete
            </Button>
          </DialogActions>
        </Card>
      </Dialog>
    </>
  );
};

export default DialogDeleteAddFeaturesList;
